/* Signature Change Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aurora Dawn": "Evocative codename: 'first light'.", "Cinder Fox": "Alliterative animal codename in the Ubuntu style.", "Harbor Mist": "Landmark codename in the macOS style.", "Ember 7": "Evocative codename with disciplined version number.", "Willow Song": "Evocative nature codename.", "Quartz 12": "Mineral codename with disciplined version number.", "Aurora Dawn LTS": "Signature release-surname compound.", "Cinder Fox RC": "Signature release-surname compound.", "Harbor Mist SP2": "Signature release-surname compound.", "Ember 7.1": "Signature point-release form."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aurora Dawn';
console.log(lookup(q));

